suppressPackageStartupMessages({library(data.table);library(pROC)})
d <- 'results'; pass <- character(); fail <- character(); chk <- function(ok,msg){if(ok) pass<<-c(pass,paste('PASS',msg)) else fail<<-c(fail,paste('FAIL',msg))}
sm<-fread(file.path(d,'sample_metadata_full.csv')); inc<-sm[include==TRUE]
chk(nrow(inc)==139,'included sample count is 139'); chk(!anyDuplicated(inc$GSM),'included GSM IDs are unique'); chk(!anyDuplicated(paste(inc$GSE,inc$patient_id)),'included patient IDs are unique within GSE')
g27<-inc[GSE=='GSE32707']; chk(all(g27$raw_group%in%c('Sepsis Day 0','se/ARDS Day 0')),'GSE32707 inclusion is Day 0 only'); chk(nrow(g27[raw_group=='Sepsis Day 0'])==30 && nrow(g27[raw_group=='se/ARDS Day 0'])==18,'GSE32707 group counts are 30/18')
pa<-fread(file.path(d,'platform_mapping_audit.csv')); chk(all(pa$platform==c('GPL571','GPL10558','GPL6244')),'platform IDs match GEO series'); chk(all(pa$hub_gene_coverage==20),'all 20 Hub genes map on every platform')
hm<-fread(file.path(d,'hub_gene_probe_mapping.csv')); hubs<-scan(file.path(d,'figure2d_hub_genes.txt'),what=''); chk(all(hubs%in%hm$gene),'Hub mapping table contains all 20 genes'); chk(all(fread(file.path(d,'preprocessing_audit.csv'))$log2_applied==c(FALSE,TRUE,FALSE)),'log2 decisions are prespecified and dataset-specific')
pred<-fread(file.path(d,'outer_test_predictions.csv')); sp<-fread(file.path(d,'outer_fold_splits.csv')); chk(nrow(unique(sp[role=='test',.(GSM,outer_fold)]))==139,'each sample has one outer-test assignment'); chk(length(unique(pred$model))==8,'all eight models are present')
fa<-fread(file.path(d,'fold_auc.csv')); rec<-pred[,.(recomputed_AUC=as.numeric(auc(y,prob,direction='<'))),by=.(outer_fold,model)]; mm<-merge(fa,rec,by=c('outer_fold','model')); chk(max(abs(mm$AUC-mm$recomputed_AUC))<1e-10,'fold AUC reproduces from OOF probabilities'); chk(all(fa[, .N, by=model]$N==5),'each model has five outer-fold AUCs')
gs<-fread(file.path(d,'outer_training_gene_statistics.csv')); chk(nrow(gs)==100 && all(gs$gene%in%hubs),'all fold statistics are restricted to the 20 genes'); chk(all(gs$selection_reason%in%c('significant_threshold','top5_rank_fallback','not_selected')),'selection reasons are explicit')
pt<-fread(file.path(d,'PTGS2_sample_expression.csv')); pts<-pt[,.(calc_logFC=mean(PTGS2_expression[label=='SILI'])-mean(PTGS2_expression[label=='Control'])),by=GSE]; ps<-fread(file.path(d,'PTGS2_direction_summary.csv')); mpt<-merge(pts,ps,by='GSE'); chk(max(abs(mpt$calc_logFC-mpt$PTGS2_logFC_SILI_minus_Control))<1e-10,'PTGS2 summary reproduces from sample values')
writeLines(c(pass,fail),file.path(d,'automated_acceptance_tests.txt')); if(length(fail)) quit(status=1)
